/* fdtd-2d.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "fdtd-2d.h"


/* Array initialization. */
static
void init_array (int tmax,
		 int nx,
		 int ny,
		 DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int i, j;

  for (i = 0; i < tmax; i++)
    _fict_[i] = (DATA_TYPE) i;

  for (i = 0; i < nx; i++)
    for (j = 0; j < ny; j++)
      {
	ex[i][j] = ((DATA_TYPE) i*(j+1)) / nx;
	ey[i][j] = ((DATA_TYPE) i*(j+2)) / ny;
	hz[i][j] = ((DATA_TYPE) i*(j+3)) / nx;
      }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int nx,
		 int ny,
		 DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("ex");
  for (i = 0; i < nx; i++)
    for (j = 0; j < ny; j++) {
      if ((i * nx + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, ex[i][j]);
    }
  POLYBENCH_DUMP_END("ex");
  POLYBENCH_DUMP_FINISH;

  POLYBENCH_DUMP_BEGIN("ey");
  for (i = 0; i < nx; i++)
    for (j = 0; j < ny; j++) {
      if ((i * nx + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, ey[i][j]);
    }
  POLYBENCH_DUMP_END("ey");

  POLYBENCH_DUMP_BEGIN("hz");
  for (i = 0; i < nx; i++)
    for (j = 0; j < ny; j++) {
      if ((i * nx + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, hz[i][j]);
    }
  POLYBENCH_DUMP_END("hz");
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations applied:
 *  - Use of restrict-qualified local aliases for the 2D arrays to
 *    improve alias analysis and vectorization.
 *  - Hoisting of scalar constants out of the loops.
 *  - Introduction of a sliding window in the ex-update loop to
 *    avoid redundant loads of hz[i][j-1].
 *  - OpenMP parallelization of the spatial loops with a single
 *    parallel region around the time loop (when compiled with
 *    OpenMP support). Without OpenMP, the pragmas are ignored and
 *    the code behaves as the original sequential version.
 *  - Per-row pointer temporaries inside inner loops to reduce
 *    pointer arithmetic and improve cache locality.
 *
 * The numerical computation and update order are preserved exactly.
 */
static
void kernel_fdtd_2d[[gnu::flatten, gnu::noinline]](int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;

  /* Local aliases with explicit restrict.
   * POLYBENCH_2D expands to a pointer-to-VLA type, so this keeps the
   * original layout but tells the compiler that ex_, ey_ and hz_
   * do not alias each other.
   */
  DATA_TYPE (* restrict ex_)[ny] = ex;
  DATA_TYPE (* restrict ey_)[ny] = ey;
  DATA_TYPE (* restrict hz_)[ny] = hz;

  /* Cached loop bounds (PolyBench-provided, possibly smaller than
   * the full nx/ny) to help the optimizer.
   */
  const int tmax_ = _PB_TMAX;
  const int nx_   = _PB_NX;
  const int ny_   = _PB_NY;

  /* Hoist scalar constants out of the loops. */
  const DATA_TYPE c0_5 = SCALAR_VAL(0.5);
  const DATA_TYPE c0_7 = SCALAR_VAL(0.7);

#pragma scop

  /* Single parallel region to amortize thread creation cost.
   * When compiled without OpenMP support, all #pragma omp lines
   * are ignored by the compiler and the code runs sequentially
   * with identical semantics to the original version.
   */
#pragma omp parallel default(none) shared(ex_,ey_,hz_,_fict_) \
                         private(t,i,j) \
                         firstprivate(tmax_,nx_,ny_,c0_5,c0_7)
  {
    for (t = 0; t < tmax_; t++)
    {
      /* Time-dependent boundary value. */
      const DATA_TYPE fict_t = _fict_[t];

      /* ey[0][j] = _fict_[t];  j in [0, ny_) */
#pragma omp for
      for (j = 0; j < ny_; j++)
        ey_[0][j] = fict_t;

      /* ey update for i in [1, nx_):
       * ey[i][j] -= 0.5 * (hz[i][j] - hz[i-1][j]);
       */
#pragma omp for
      for (i = 1; i < nx_; i++)
      {
        DATA_TYPE * restrict ey_i   = ey_[i];
        DATA_TYPE * restrict hz_i   = hz_[i];
        DATA_TYPE * restrict hz_im1 = hz_[i-1];

        /* Inner loop is fully independent and vectorizable. */
#pragma omp simd
        for (j = 0; j < ny_; j++)
          ey_i[j] -= c0_5 * (hz_i[j] - hz_im1[j]);
      }

      /* ex update for all rows:
       * for j >= 1:
       *   ex[i][j] -= 0.5 * (hz[i][j] - hz[i][j-1]);
       *
       * We keep j=0 untouched as in the original code.
       * A sliding window along j avoids reloading hz[i][j-1].
       */
#pragma omp for
      for (i = 0; i < nx_; i++)
      {
        DATA_TYPE * restrict ex_i = ex_[i];
        DATA_TYPE * restrict hz_i = hz_[i];

        DATA_TYPE hz_prev = hz_i[0];

#pragma omp simd
        for (j = 1; j < ny_; j++)
        {
          const DATA_TYPE hz_curr = hz_i[j];
          ex_i[j] -= c0_5 * (hz_curr - hz_prev);
          hz_prev = hz_curr;
        }
      }

      /* hz update for interior points:
       * for i in [0, nx_-1), j in [0, ny_-1):
       *   hz[i][j] -= 0.7 * (ex[i][j+1] - ex[i][j]
       *                      + ey[i+1][j] - ey[i][j]);
       */
#pragma omp for
      for (i = 0; i < nx_ - 1; i++)
      {
        DATA_TYPE * restrict hz_i  = hz_[i];
        DATA_TYPE * restrict ex_i  = ex_[i];
        DATA_TYPE * restrict ey_i  = ey_[i];
        DATA_TYPE * restrict ey_ip = ey_[i+1];

#pragma omp simd
        for (j = 0; j < ny_ - 1; j++)
        {
          hz_i[j] -= c0_7 *
                     ((ex_i[j+1] - ex_i[j]) +
                      (ey_ip[j]   - ey_i[j]));
        }
      }
      /* Default barriers at the end of each omp for ensure that:
       *  - all ey updates are complete before ex updates,
       *  - all ex updates are complete before hz updates,
       *  - and all updates for timestep t are complete before t+1.
       * This preserves the original sequential dependence structure.
       */
    }
  }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int tmax = TMAX;
  int nx = NX;
  int ny = NY;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(ex,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(ey,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(hz,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_1D_ARRAY_DECL(_fict_,DATA_TYPE,TMAX,tmax);

  /* Initialize array(s). */
  init_array (tmax, nx, ny,
	      POLYBENCH_ARRAY(ex),
	      POLYBENCH_ARRAY(ey),
	      POLYBENCH_ARRAY(hz),
	      POLYBENCH_ARRAY(_fict_));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_fdtd_2d (tmax, nx, ny,
		  POLYBENCH_ARRAY(ex),
		  POLYBENCH_ARRAY(ey),
		  POLYBENCH_ARRAY(hz),
		  POLYBENCH_ARRAY(_fict_));


  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(nx, ny, POLYBENCH_ARRAY(ex),
				    POLYBENCH_ARRAY(ey),
				    POLYBENCH_ARRAY(hz)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(ex);
  POLYBENCH_FREE_ARRAY(ey);
  POLYBENCH_FREE_ARRAY(hz);
  POLYBENCH_FREE_ARRAY(_fict_);

  return 0;
}
