#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Optional: enable OpenMP pragmas when compiled with -fopenmp. */
#ifdef _OPENMP
# include <omp.h>
#endif

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "fdtd-2d.h"


/* Array initialization.
 *
 * Optimizations:
 *  - Use restrict-qualified local pointers to help the compiler
 *    with alias analysis and vectorization.
 *  - Allow (optional) OpenMP parallelization of the initialization
 *    loops without changing their semantics.
 */
static
void init_array (int tmax,
		 int nx,
		 int ny,
		 DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int i, j;

  /* Local restrict-qualified aliases improve vectorization. */
  DATA_TYPE (* __restrict ex_)[ny] = ex;
  DATA_TYPE (* __restrict ey_)[ny] = ey;
  DATA_TYPE (* __restrict hz_)[ny] = hz;
  DATA_TYPE * __restrict fict_    = _fict_;

  /* Initialize fictitious source term. */
  #pragma omp parallel for if (tmax > 512)
  for (i = 0; i < tmax; i++)
    fict_[i] = (DATA_TYPE) i;

  /* Initialize field arrays. Each element is written exactly once. */
  #pragma omp parallel for collapse(2) if ((long)nx * (long)ny > 4096L)
  for (i = 0; i < nx; i++)
    for (j = 0; j < ny; j++)
      {
        /* Arithmetic kept identical to original code. */
	ex_[i][j] = ((DATA_TYPE) i*(j+1)) / nx;
	ey_[i][j] = ((DATA_TYPE) i*(j+2)) / ny;
	hz_[i][j] = ((DATA_TYPE) i*(j+3)) / nx;
      }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int nx,
		 int ny,
		 DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		 DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("ex");
  for (i = 0; i < nx; i++)
    for (j = 0; j < ny; j++) {
      if ((i * nx + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, ex[i][j]);
    }
  POLYBENCH_DUMP_END("ex");
  POLYBENCH_DUMP_FINISH;

  POLYBENCH_DUMP_BEGIN("ey");
  for (i = 0; i < nx; i++)
    for (j = 0; j < ny; j++) {
      if ((i * nx + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, ey[i][j]);
    }
  POLYBENCH_DUMP_END("ey");

  POLYBENCH_DUMP_BEGIN("hz");
  for (i = 0; i < nx; i++)
    for (j = 0; j < ny; j++) {
      if ((i * nx + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, hz[i][j]);
    }
  POLYBENCH_DUMP_END("hz");
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations:
 *  - Introduce local restrict-qualified aliases for better alias
 *    analysis and vectorization.
 *  - Hoist scalar coefficients out of the loops.
 *  - Fuse the two central update loops (ey and ex) over the
 *    interior domain to improve reuse of hz[i][j].
 *  - Keep boundary updates separate to avoid conditionals in
 *    the hot interior loop; this preserves exact per-element
 *    update formulas.
 *  - Apply OpenMP parallelism over space dimensions for each
 *    time step (when compiled with -fopenmp).
 *  - Tile the hz update for improved cache locality; tile sizes
 *    can be tuned via the TILE_I/TILE_J constants.
 *
 * The update order w.r.t. time steps and between ex/ey/hz is
 * preserved: for each t, all ex/ey updates are completed before
 * any hz update, exactly as in the original code.
 */
static
void kernel_fdtd_2d[[gnu::flatten, gnu::noinline]](int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  /* The original code declared these; keep them for clarity,
     though we now use loop-local indices. */
  int t, i, j;
  (void)t; (void)i; (void)j; /* suppress unused warnings */

  /* Tunable tiling parameters for the hz update. Adjust these
   * for specific cache hierarchies if needed. */
  enum { TILE_I = 32, TILE_J = 32 };

  /* Local restrict-qualified aliases.  Dimensions use the full
   * runtime sizes (nx, ny); the loop bounds below use the
   * PolyBench _PB_* macros, which are <= these sizes. */
