  DATA_TYPE (* __restrict ey_)[ny]   = ey;
  DATA_TYPE (* __restrict hz_)[ny]   = hz;
  DATA_TYPE * __restrict fict_       = _fict_;

  const int nx_   = _PB_NX;
  const int ny_   = _PB_NY;
  const int tmax_ = _PB_TMAX;

  const DATA_TYPE half = SCALAR_VAL(0.5);
  const DATA_TYPE c07  = SCALAR_VAL(0.7);

#pragma scop

  /* Parallelize space loops; time loop kept sequential because of
   * true dependences across time steps.  Without -fopenmp, all
   * pragmas are ignored and the code reduces to the sequential
   * version with the same loop structure. */
  #pragma omp parallel
  {
    for (t = 0; t < tmax_; t++)
    {
      const DATA_TYPE fict_t = fict_[t];

      /* 1. Boundary condition on ey at i = 0: ey[0][j] = _fict_[t] */
      #pragma omp for simd
      for (j = 0; j < ny_; j++)
        ey_[0][j] = fict_t;

      /* 2. Fused interior update of ey and ex for i >= 1, j >= 1.
       *
       * Original:
       *   for i = 1..nx_-1, j = 0..ny_-1:
       *     ey[i][j] -= 0.5 * (hz[i][j] - hz[i-1][j]);
       *   for i = 0..nx_-1, j = 1..ny_-1:
       *     ex[i][j] -= 0.5 * (hz[i][j] - hz[i][j-1]);
