      for (i = 1; i < nx_; i++)
        for (j = 1; j < ny_; j++)
        {
          const DATA_TYPE hz_ij = hz_[i][j];
          ey_[i][j] -= half * (hz_ij - hz_[i-1][j]);
          ex_[i][j] -= half * (hz_ij - hz_[i][j-1]);
        }

      /* 3. Remaining ey boundary: j = 0, i >= 1.
       *    Matches original ey update for column j = 0.
       */
      #pragma omp for simd
      for (i = 1; i < nx_; i++)
      {
        const DATA_TYPE hz_i0 = hz_[i][0];
        ey_[i][0] -= half * (hz_i0 - hz_[i-1][0]);
      }

      /* 4. Remaining ex boundary: i = 0, j >= 1.
       *    Matches original ex update for row i = 0.
       */
      #pragma omp for simd
      for (j = 1; j < ny_; j++)
      {
        const DATA_TYPE hz_0j = hz_[0][j];
        ex_[0][j] -= half * (hz_0j - hz_[0][j-1]);
      }

      /* 5. Update hz over the interior (i = 0..nx_-2, j = 0..ny_-2).
       *
       * We apply 2D tiling in (i, j) to improve cache reuse of
       * ex and ey. Tiles are sized TILE_I x TILE_J and handle
       * any non-divisible tails via min bounds.
       */
      #pragma omp for collapse(2)
      for (int ii = 0; ii < nx_ - 1; ii += TILE_I)
        for (int jj = 0; jj < ny_ - 1; jj += TILE_J)
        {
          const int i_end = (ii + TILE_I < nx_ - 1) ? (ii + TILE_I) : (nx_ - 1);
          const int j_end = (jj + TILE_J < ny_ - 1) ? (jj + TILE_J) : (ny_ - 1);

          for (i = ii; i < i_end; i++)
          {
            #pragma omp simd
            for (j = jj; j < j_end; j++)
            {
              /* Original formula:
               * hz[i][j] -= 0.7 * ( ex[i][j+1] - ex[i][j]
               *                    + ey[i+1][j] - ey[i][j] );
               */
              hz_[i][j] -= c07 * ( (ex_[i][j+1] - ex_[i][j]) +
                                   (ey_[i+1][j] - ey_[i][j]) );
            }
          }
        }

      /* Implicit barrier at end of each omp for keeps the original
       * ordering between stages for each t. */
    } /* end time loop */
  } /* end parallel region */

#pragma endscop
}


